input.command:
mkdir -p /tmp/shim && cat > /tmp/shim/test10.mjs <<'EOF'
// THROWAWAY harness self-test shim (lives in /tmp, NOT part of the deliverable).
// Proxies the reference binary so we can prove /tmp/orch_verify.sh reports 0 failures
// on a behaviourally identical target -- i.e. the harness is not spuriously failing.
import { spawnSync } from 'node:child_process';
const r = spawnSync('/workspace/dataset/test10_executable', process.argv.slice(2), { stdio: 'inherit' });
process.exitCode = r.status ?? 1;
EOF
JS=/tmp/shim/test10.mjs bash /tmp/orch_verify.sh 2>&1 | tail -25

D=/opt/uiuc-agent/home/.claude/projects/-workspace/a846ac30-191b-48c0-8eaa-2ceb7cc42016/subagents/workflows/wf_ca8277f6-c10
ls -la "$D" 2>/dev/null | head -30
echo "=== journal (labels + status) ==="
[ -f "$D/journal.jsonl" ] && node -e '
const fs=require("fs");
const L=fs.readFileSync(process.argv[1],"utf8").trim().split("\n");
for(const l of L){try{const j=JSON.parse(l);
const lab=j.label||j.opts?.label||"";
const ph=j.phase||j.opts?.phase||"";
const res=j.result!==undefined?(typeof j.result==="string"?`str(${j.result.length})`:JSON.stringify(j.result).slice(0,120)):"";
console.log([j.type||j.kind||"?",ph,lab,res].filter(Boolean).join(" | "));
}catch(e){console.log("raw:",l.slice(0,160));}}
' "$D/journal.jsonl" | tail -40 || echo "(no journal yet)"

sleep 580; D=/opt/uiuc-agent/home/.claude/projects/-workspace/a846ac30-191b-48c0-8eaa-2ceb7cc42016/subagents/workflows/wf_ca8277f6-c10
echo "=== agents: $(ls "$D"/agent-*.jsonl 2>/dev/null | wc -l) ==="
echo "=== journal results ==="; node -e '
const fs=require("fs");const L=fs.readFileSync(process.argv[1],"utf8").trim().split("\n");
let n=0;for(const l of L){try{const j=JSON.parse(l);if(j.type==="result"||j.result!==undefined){n++;}}catch(e){}}
console.log("completed agent results:",n,"of",L.length,"journal lines");
' "$D/journal.jsonl" 2>/dev/null
echo "=== candidates ==="; ls /tmp/cand-a /tmp/cand-b 2>/dev/null || echo "(not yet)"
echo "=== /output ==="; ls -R /output 2>/dev/null
